#!/bin/sh
development_menu(){ while :; do c=$(ui_menu Development 'Developer toolchains and configuration.' git 'Configure Git' build 'Install build toolchain' python 'Configure Python/pip' rust 'Configure Cargo/Rust' node 'Configure Node package managers' go 'Configure Go' cmake 'Configure CMake/Ninja' debug 'Install debugging tools' env 'Edit development environment') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in git) ensure_template gitconfig "$CURRENT_HOME/.gitconfig";; build) bundle_menu;; python) mkdir -p "$CURRENT_HOME/.config/pip"; ensure_template pip "$CURRENT_HOME/.config/pip/pip.conf";; rust) mkdir -p "$CURRENT_HOME/.cargo"; ensure_template cargo "$CURRENT_HOME/.cargo/config.toml";; node) mkdir -p "$CURRENT_HOME/.config"; ensure_template npmrc "$CURRENT_HOME/.npmrc";; go) replace_block "$CURRENT_HOME/.profile" go 'export GOPATH="$HOME/go"\nexport PATH="$GOPATH/bin:$PATH"';; cmake) replace_block "$CURRENT_HOME/.profile" cmake 'export CMAKE_GENERATOR=Ninja\nexport CMAKE_BUILD_PARALLEL_LEVEL=2';; debug) p='gdb strace ltrace file binutils'; run_capture Debug pkg_install $p;; env) edit_file "$CURRENT_HOME/.config/ish-aok-development.env";; esac; done; }
